// Unit tests for codec_v2.mjs. Static. No emulator import.
// Stops at the first failed assertion. Do not edit this file after it has run.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import {
  CRC_BITS, DIM_H, DIM_H_BITS, DIM_V, DIM_V_BITS, FIELD_BITS, MARKER, MARKER_BITS,
  PAD_BITS, PAYLOAD_BITS, POSES, POSITION_BITS, POSITION_MAX, PROFILE_A, RECORD_BYTES,
  SIZE_BITS, SPARE_BITS, STEP_H, STEP_H_BITS, STEP_V, STEP_V_BITS, USED_BITS, USED_BYTES,
  VERSION, VERSION_BITS, ZONE, ZONE_BITS,
  crc16, decode, encode,
} from './codec_v2.mjs';

const domain = JSON.parse(readFileSync('work/out/domain-t10b.json', 'utf8'));
const ranges = JSON.parse(readFileSync(
  'ref/tasks/T10-afon-profile-storage-5b82/run-20261119-163743/work/out/ranges-t10c.json',
  'utf8',
));
const codecSrc = readFileSync(new URL('./codec_v2.mjs', import.meta.url), 'utf8');
for (const token of ['0x5962', '0x99a1', '0x5b82', 'BANKS']) {
  assert.equal(codecSrc.includes(token), false, token);
}

function tableOf(ui) {
  const row = ranges.descriptors.find((r) => r.ui === ui);
  assert.ok(row && row.records.length === 1, 'ui ' + ui);
  assert.equal(row.records[0].table.values_truncated, false);
  return row.records[0].table.values_head;
}
assert.deepEqual(domain.domain.zone.values, ZONE);
assert.deepEqual(domain.domain.dim_v.values, DIM_V);
assert.deepEqual(domain.domain.dim_h.values, DIM_H);
assert.deepEqual(domain.domain.step_v.values, STEP_V);
assert.deepEqual(domain.domain.step_h.values, STEP_H);
assert.deepEqual(tableOf(1333), ZONE);
assert.deepEqual(tableOf(1645), ZONE);
assert.deepEqual(tableOf(1643), ZONE);
assert.deepEqual(tableOf(1657), domain.descriptors.dim_v.descriptor_values);
assert.deepEqual(tableOf(1658), domain.descriptors.dim_h.descriptor_values);
assert.deepEqual(tableOf(1667), domain.descriptors.step_v.descriptor_values);
assert.deepEqual(tableOf(1668), domain.descriptors.step_h.descriptor_values);
assert.deepEqual([0, ...tableOf(1657)], DIM_V);
assert.deepEqual([0, ...tableOf(1658)], DIM_H);
assert.deepEqual([0, ...tableOf(1667)], STEP_V);
assert.deepEqual([0, ...tableOf(1668)], STEP_H);
assert.ok(!tableOf(1657).includes(0));
assert.ok(!tableOf(1668).includes(0));
const pos = ranges.descriptors.find((r) => r.ui === 1339).records[0].table;
assert.equal(pos.count, POSITION_MAX + 1);
assert.equal(pos.min, 0);
assert.equal(pos.max, POSITION_MAX);
assert.equal(domain.descriptors.position.max, POSITION_MAX);
assert.equal(domain.descriptors.size.records, 0);
assert.equal(ranges.descriptors.find((r) => r.ui === 1803).records.length, 0);
assert.equal(domain.packing.fits, true);
assert.equal(domain.packing.shortfall_bits, 0);
assert.equal(PAYLOAD_BITS, domain.packing.payload_bits);
assert.equal(FIELD_BITS, domain.packing.field_bits);
assert.equal(PAD_BITS, domain.packing.pad_bits);
assert.equal(CRC_BITS, domain.packing.crc_bits);
assert.equal(USED_BITS, domain.packing.used_bits);
assert.equal(USED_BYTES, domain.packing.used_bytes);
assert.equal(SPARE_BITS, domain.packing.spare_bits);
assert.equal(RECORD_BYTES * 8, 208);
assert.equal(ZONE_BITS, 4);
assert.equal(SIZE_BITS, 8);
assert.equal(POSITION_BITS, 11);
assert.equal(DIM_V_BITS, 4);
assert.equal(DIM_H_BITS, 4);
assert.equal(STEP_V_BITS, 3);
assert.equal(STEP_H_BITS, 4);
assert.deepEqual(domain.packing.poses, POSES);
for (const row of domain.registration) {
  assert.deepEqual(row.unique, [0]);
}
assert.equal(domain.reset_equals_fresh, true);
for (const values of Object.values(domain.reset_outside_domain)) assert.deepEqual(values, []);

let roundTrips = 0;
let rejected = 0;

function sameBytes(a, b) {
  assert.equal(a.length, b.length);
  for (let i = 0; i < a.length; i++) assert.equal(a[i], b[i], 'byte ' + i);
}

function roundTrip(profile) {
  const bytes = encode(profile);
  assert.equal(bytes.length, RECORD_BYTES);
  assert.equal(bytes[0], MARKER & 0xff);
  assert.equal(bytes[1], (MARKER >> 8) & 0xff);
  assert.equal(bytes[2], VERSION);
  for (let i = USED_BYTES; i < RECORD_BYTES; i++) assert.equal(bytes[i], 0);
  const back = decode(bytes);
  assert.deepEqual(back, profile);
  sameBytes(encode(back), bytes);
  roundTrips += 1;
  return bytes;
}

function mustThrow(profile) {
  let threw = false;
  try {
    encode(profile);
  } catch (e) {
    if (!(e instanceof RangeError)) throw e;
    threw = true;
  }
  if (!threw) assert.fail('accepted out-of-domain value');
  rejected += 1;
}

function clone(profile) {
  return structuredClone(profile);
}

const PROFILE_ZERO = {
  zone: { landscape: 0, exif6: 0, exif8: 0 },
  size: 0,
  position: { landscape: 0, exif6: 0, exif8: 0 },
  dim: Array(10).fill(0),
  step: Array(8).fill(0),
};

// T10 profile A, and the registration / T3l all-zero custom profile.
roundTrip(PROFILE_A);
roundTrip(PROFILE_ZERO);
const zeroCustom = clone(PROFILE_A);
zeroCustom.dim = Array(10).fill(0);
zeroCustom.step = Array(8).fill(0);
roundTrip(zeroCustom);

// Each single zero field, with the other fields left at legal non-zero values.
for (let i = 0; i < 10; i++) {
  const p = clone(PROFILE_A);
  p.dim[i] = 0;
  roundTrip(p);
}
for (let i = 0; i < 8; i++) {
  const p = clone(PROFILE_A);
  p.step[i] = 0;
  roundTrip(p);
}
for (const pose of POSES) {
  const zone = clone(PROFILE_A);
  zone.zone[pose] = 0;
  roundTrip(zone);
  const position = clone(PROFILE_A);
  position.position[pose] = 0;
  roundTrip(position);
}
const sizeZero = clone(PROFILE_A);
sizeZero.size = 255;
roundTrip(sizeZero);
sizeZero.size = 0;
roundTrip(sizeZero);

// Mixed initialized and zero custom arrays, including the T3l C1 and C2 landings.
function zeroAround(dim, step) {
  return {
    zone: { landscape: 0, exif6: 0, exif8: 0 },
    size: 0,
    position: { landscape: 0, exif6: 0, exif8: 0 },
    dim: dim.slice(),
    step: step.slice(),
  };
}
roundTrip(zeroAround(domain.t3l.c1_from_zero.dim, domain.t3l.c1_from_zero.step));
roundTrip(zeroAround(domain.t3l.c1_and_c2.dim, domain.t3l.c1_and_c2.step));
const mixed = clone(PROFILE_A);
mixed.dim[0] = 0;
mixed.dim[3] = 0;
mixed.dim[8] = 0;
mixed.step[1] = 0;
mixed.step[4] = 0;
mixed.step[7] = 0;
roundTrip(mixed);
roundTrip(zeroAround(
  [27, 0, 27, 0, 27, 0, 27, 0, 27, 0],
  [5, 0, 5, 0, 5, 0, 5, 0],
));
roundTrip(zeroAround(
  [0, 39, 0, 39, 0, 39, 0, 39, 0, 39],
  [0, 8, 0, 8, 0, 8, 0, 8],
));

// T8c reset values at the saved pose cells, and the same image at the change cells.
roundTrip(domain.reset_profile_saved_index);
roundTrip(domain.reset_profile_change_index);

// Low and high end of every field.
for (const pose of POSES) {
  for (const value of [0, 10]) {
    const p = clone(PROFILE_A);
    p.zone[pose] = value;
    roundTrip(p);
  }
  for (const value of [0, POSITION_MAX]) {
    const p = clone(PROFILE_A);
    p.position[pose] = value;
    roundTrip(p);
  }
}
for (const size of [0, 255]) {
  const p = clone(PROFILE_A);
  p.size = size;
  roundTrip(p);
}
for (let i = 0; i < 10; i++) {
  const [low, high] = i % 2 === 0 ? [0, 27] : [0, 39];
  for (const value of [low, high]) {
    const p = clone(PROFILE_A);
    p.dim[i] = value;
    roundTrip(p);
  }
}
for (let i = 0; i < 8; i++) {
  const [low, high] = i % 2 === 0 ? [0, 5] : [0, 8];
  for (const value of [low, high]) {
    const p = clone(PROFILE_A);
    p.step[i] = value;
    roundTrip(p);
  }
}

// Every value of each enumerated domain.
for (const pose of POSES) {
  for (const value of ZONE) {
    const p = clone(PROFILE_A);
    p.zone[pose] = value;
    roundTrip(p);
  }
  for (let value = 0; value <= POSITION_MAX; value++) {
    const p = clone(PROFILE_A);
    p.position[pose] = value;
    roundTrip(p);
  }
}
for (let size = 0; size <= 255; size++) {
  const p = clone(PROFILE_A);
  p.size = size;
  roundTrip(p);
}
for (let i = 0; i < 10; i++) {
  const table = i % 2 === 0 ? DIM_V : DIM_H;
  for (const value of table) {
    const p = clone(PROFILE_A);
    p.dim[i] = value;
    roundTrip(p);
  }
}
for (let i = 0; i < 8; i++) {
  const table = i % 2 === 0 ? STEP_V : STEP_H;
  for (const value of table) {
    const p = clone(PROFILE_A);
    p.step[i] = value;
    roundTrip(p);
  }
}

// Each out-of-domain cell value is an encode error, not a clamp.
const cell = clone(PROFILE_A);
for (const pose of POSES) {
  for (let value = 0; value <= 255; value++) {
    if (ZONE.includes(value)) continue;
    cell.zone[pose] = value;
    mustThrow(cell);
  }
  cell.zone[pose] = PROFILE_A.zone[pose];
  for (let value = POSITION_MAX + 1; value <= 65535; value++) {
    cell.position[pose] = value;
    mustThrow(cell);
  }
  cell.position[pose] = -1;
  mustThrow(cell);
  cell.position[pose] = 1.5;
  mustThrow(cell);
  cell.position[pose] = PROFILE_A.position[pose];
}
for (const value of [-1, 256, 1.5]) {
  cell.size = value;
  mustThrow(cell);
}
cell.size = PROFILE_A.size;
for (let i = 0; i < 10; i++) {
  const table = i % 2 === 0 ? DIM_V : DIM_H;
  for (let value = 0; value <= 255; value++) {
    if (table.includes(value)) continue;
    cell.dim[i] = value;
    mustThrow(cell);
  }
  cell.dim[i] = PROFILE_A.dim[i];
}
for (let i = 0; i < 8; i++) {
  const table = i % 2 === 0 ? STEP_V : STEP_H;
  for (let value = 0; value <= 255; value++) {
    if (table.includes(value)) continue;
    cell.step[i] = value;
    mustThrow(cell);
  }
  cell.step[i] = PROFILE_A.step[i];
}
const oldBanks = clone(PROFILE_A);
oldBanks.zone = { 1: 2, 5: 6, 3: 1 };
mustThrow(oldBanks);
mustThrow(null);
mustThrow({ ...PROFILE_A, dim: PROFILE_A.dim.slice(0, 9) });
mustThrow({ ...PROFILE_A, step: PROFILE_A.step.slice(0, 7) });

// T10 corruption cases, on this layout's bit positions.
function poke(buf, bit, width, value) {
  for (let i = 0; i < width; i++) {
    const at = bit + i;
    const want = (value >>> i) & 1;
    const has = (buf[at >> 3] >> (at & 7)) & 1;
    if (has !== want) buf[at >> 3] ^= 1 << (at & 7);
  }
  return buf;
}
function resign(buf) {
  const crc = crc16(buf.subarray(0, USED_BYTES - 2));
  buf[USED_BYTES - 2] = crc & 0xff;
  buf[USED_BYTES - 1] = (crc >> 8) & 0xff;
  return buf;
}
let cursor = 0;
cursor += MARKER_BITS;
const versionBit = cursor;
cursor += VERSION_BITS;
const zoneBit = cursor;
cursor += ZONE_BITS * POSES.length;
cursor += SIZE_BITS;
const positionBit = cursor;
cursor += POSITION_BITS * POSES.length;
const dimVBit = cursor;
cursor += DIM_V_BITS * 5;
cursor += DIM_H_BITS * 5;
cursor += STEP_V_BITS * 4;
const stepHBit = cursor;
cursor += STEP_H_BITS * 4;
assert.equal(cursor, FIELD_BITS);

assert.equal(decode(new Uint8Array(RECORD_BYTES)), null);
assert.equal(decode(new Uint8Array(RECORD_BYTES).fill(0xff)), null);
assert.equal(decode(new Uint8Array(25)), null);
const stock = new Uint8Array(RECORD_BYTES);
for (let i = 0; i < RECORD_BYTES; i += 2) {
  stock[i] = 0x80;
  stock[i + 1] = 0x0c;
}
assert.equal(decode(stock), null);
assert.equal(stock[0] | (stock[1] << 8), 0x0c80);
assert.notEqual(MARKER, 0);
assert.notEqual(MARKER, 0x0c80);

const good = roundTrip(PROFILE_A);
for (let bit = 0; bit < RECORD_BYTES * 8; bit++) {
  const flipped = Uint8Array.from(good);
  flipped[bit >> 3] ^= 1 << (bit & 7);
  assert.equal(decode(flipped), null, 'bit ' + bit);
}
const zeroRecord = roundTrip(PROFILE_ZERO);
for (let bit = 0; bit < RECORD_BYTES * 8; bit++) {
  const flipped = Uint8Array.from(zeroRecord);
  flipped[bit >> 3] ^= 1 << (bit & 7);
  assert.equal(decode(flipped), null, 'zero bit ' + bit);
}

const badZone = resign(poke(Uint8Array.from(good), zoneBit, ZONE_BITS, ZONE.length));
assert.equal(decode(badZone), null);
const badDim = resign(poke(Uint8Array.from(good), dimVBit, DIM_V_BITS, DIM_V.length));
assert.equal(decode(badDim), null);
const badStep = resign(poke(Uint8Array.from(good), stepHBit, STEP_H_BITS, STEP_H.length));
assert.equal(decode(badStep), null);
const badPos = resign(poke(Uint8Array.from(good), positionBit, POSITION_BITS, POSITION_MAX + 1));
assert.equal(decode(badPos), null);
for (const version of [0, 1, 255]) {
  const badVersion = resign(poke(Uint8Array.from(good), versionBit, VERSION_BITS, version));
  assert.equal(decode(badVersion), null);
}

console.log(JSON.stringify({
  ok: true,
  version: VERSION,
  payload_bits: PAYLOAD_BITS,
  field_bits: FIELD_BITS,
  pad_bits: PAD_BITS,
  crc_bits: CRC_BITS,
  used_bytes: USED_BYTES,
  spare_bits: SPARE_BITS,
  round_trips: roundTrips,
  rejected: rejected,
  bit_flips: RECORD_BYTES * 8,
  marker: MARKER,
  shortfall_bits: 0,
}));
